package contracttest

// journeyStepsAuthorsSeries is the fourth part of the journey: the author pages, images (uploads from a local source, a refused URL, resizing and formats), renames and merges, the series pages and their updates. It ports replacement-trial.cjs journeySteps in order.
func journeyStepsAuthorsSeries(ids map[string]string) []journeyStep {
	return []journeyStep{
		{id: "author.list", who: "root", route: "/api/libraries/" + ids["library"] + "/authors", capture: "authorList"},
		{id: "author.get.terry", who: "root", routeFn: authorRoute("Terry Fixture", "")},
		{id: "author.get.terry.items", who: "root", routeFn: authorRoute("Terry Fixture", "?include=items")},
		{id: "author.get.terry.series", who: "root", routeFn: authorRoute("Terry Fixture", "?include=items,series")},
		{id: "author.get.terry.seriesonly", who: "root", routeFn: authorRoute("Terry Fixture", "?include=series")},
		{id: "author.get.ada.series", who: "root", routeFn: authorRoute("Ada Example", "?include=items,series")},
		{id: "author.get.listener", who: "listener", routeFn: authorRoute("Terry Fixture", "?include=items,series")},
		{id: "author.get.finisher", who: "finisher", routeFn: authorRoute("Ada Example", "?include=items")},
		{id: "author.get.anon", routeFn: authorRoute("Terry Fixture", "")},
		{id: "author.get.missing", who: "root", route: "/api/authors/00000000-0000-4000-8000-000000000000"},
		{id: "author.get.badid", who: "root", route: "/api/authors/not-a-uuid"},
		{id: "author.image.none", routeFn: authorRoute("Terry Fixture", "/image"), binary: "bytes"},
		{id: "author.image.none.raw", routeFn: authorRoute("Terry Fixture", "/image?raw=1"), binary: "bytes"},
		{id: "author.image.badformat", routeFn: authorRoute("Terry Fixture", "/image?format=gif"), binary: "bytes"},
		{id: "author.image.badid", route: "/api/authors/not-a-uuid/image", binary: "bytes"},
		{id: "author.image.badid.raw", route: "/api/authors/not-a-uuid/image?raw=1", binary: "bytes"},
		{id: "author.image.missing", route: "/api/authors/00000000-0000-4000-8000-000000000000/image", binary: "bytes"},
		{id: "author.image.upload.listener", who: "listener", method: "POST", routeFn: authorRoute("Terry Fixture", "/image"), bodyFn: fixtureBody("author.jpg")},
		{id: "author.image.upload.nourl", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/image"), body: map[string]any{}},
		{id: "author.image.upload.badscheme", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/image"), body: map[string]any{"url": "ftp://example.invalid/a.jpg"}},
		{id: "author.image.upload.numurl", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/image"), body: map[string]any{"url": 5}},
		{id: "author.image.upload.notimage", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/image"), bodyFn: fixtureBody("page.html")},
		{id: "author.image.upload.svg", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/image"), bodyFn: fixtureBody("icon.svg")},
		{id: "author.image.upload.404", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/image"), bodyFn: fixtureBody("missing.jpg")},
		{id: "author.image.upload.refused", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/image"), bodyFn: func(c *journeyCtx) any { return map[string]any{"url": c.deadURL + "/a.jpg"} }},
		{id: "author.image.upload.nochange", who: "root", routeFn: authorRoute("Terry Fixture", ""), capture: "terryBefore"},
		{id: "author.image.upload.ok", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/image"), bodyFn: fixtureBody("author.jpg"), events: 1},
		{id: "author.image.raw", routeFn: authorRoute("Terry Fixture", "/image?raw=1"), binary: "bytes"},
		{id: "author.image.default", routeFn: authorRoute("Terry Fixture", "/image"), binary: "bytes"},
		{id: "author.image.jpeg", routeFn: authorRoute("Terry Fixture", "/image?format=jpeg"), binary: "bytes"},
		{id: "author.image.w200", routeFn: authorRoute("Terry Fixture", "/image?width=200&format=jpeg"), binary: "bytes"},
		{id: "author.image.w100h50", routeFn: authorRoute("Terry Fixture", "/image?width=100&height=50&format=png"), binary: "bytes"},
		{id: "author.image.h120", routeFn: authorRoute("Terry Fixture", "/image?height=120&format=jpeg"), binary: "bytes"},
		{id: "author.image.w0", routeFn: authorRoute("Terry Fixture", "/image?width=0&format=jpeg"), binary: "bytes"},
		{id: "author.image.wbad", routeFn: authorRoute("Terry Fixture", "/image?width=abc&format=jpeg"), binary: "bytes"},
		{id: "author.image.clamp", routeFn: authorRoute("Terry Fixture", "/image?width=100&height=999999&format=jpeg"), binary: "bytes"},
		{id: "author.image.webp", routeFn: authorRoute("Terry Fixture", "/image?width=150&format=webp"), binary: "bytes"},
		{id: "author.image.w200.again", routeFn: authorRoute("Terry Fixture", "/image?width=200&format=jpeg"), binary: "bytes"},
		{id: "author.get.terry.afterimage", who: "root", routeFn: authorRoute("Terry Fixture", "")},
		{id: "author.update.listener", who: "listener", method: "PATCH", routeFn: authorRoute("Terry Fixture", ""), body: map[string]any{"description": "x"}},
		{id: "author.update.empty", who: "root", method: "PATCH", routeFn: authorRoute("Terry Fixture", ""), body: map[string]any{}},
		{id: "author.update.invalid", who: "root", method: "PATCH", routeFn: authorRoute("Terry Fixture", ""), body: map[string]any{"name": 5, "description": map[string]any{}, "other": "x"}},
		{id: "author.update.description", who: "root", method: "PATCH", routeFn: authorRoute("Terry Fixture", ""), body: map[string]any{"description": "A prolific fixture author.", "asin": "B000TERRY1"}, events: 1},
		{id: "author.update.nochange", who: "root", method: "PATCH", routeFn: authorRoute("Terry Fixture", ""), body: map[string]any{"description": "A prolific fixture author.", "asin": "B000TERRY1"}},
		{id: "author.update.null", who: "root", method: "PATCH", routeFn: authorRoute("Terry Fixture", ""), body: map[string]any{"asin": nil}, events: 1},
		{id: "author.match.listener", who: "listener", method: "POST", routeFn: authorRoute("Terry Fixture", "/match"), body: map[string]any{}},
		{id: "author.match.empty", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/match"), body: map[string]any{}},
		{id: "author.match.badasin", who: "root", method: "POST", routeFn: authorRoute("Terry Fixture", "/match"), body: map[string]any{"asin": "nope", "region": "uk"}},
		{id: "author.rename.ada", who: "root", method: "PATCH", routeFn: authorRoute("Ada Example", ""), body: map[string]any{"name": "Ada Renamed"}, events: 2},
		{id: "author.after.rename.list", who: "root", route: "/api/libraries/" + ids["library"] + "/authors"},
		{id: "author.after.rename.item", who: "root", route: "/api/items/" + ids["novel"] + "?expanded=1"},
		{id: "author.rename.lowercase", who: "root", method: "PATCH", routeFn: authorRoute("Ada Example", ""), body: map[string]any{"name": "ada renamed again"}, events: 2},
		{id: "author.merge", who: "root", method: "PATCH", routeFn: authorRoute("Ada Example", ""), body: map[string]any{"name": "Terry Fixture"}, events: 3},
		{id: "author.after.merge.ada", who: "root", routeFn: authorRoute("Ada Example", "")},
		{id: "author.after.merge.terry", who: "root", routeFn: authorRoute("Terry Fixture", "?include=items,series")},
		{id: "author.after.merge.list", who: "root", route: "/api/libraries/" + ids["library"] + "/authors"},
		{id: "author.after.merge.item", who: "root", route: "/api/items/" + ids["novel"] + "?expanded=1"},
		{id: "author.temp.create", who: "root", method: "PATCH", route: "/api/items/" + ids["saga2"] + "/media", body: map[string]any{"metadata": map[string]any{"authors": []any{map[string]any{"name": "Terry Fixture"}, map[string]any{"name": "Temp Author"}}}}},
		{id: "author.temp.list", who: "root", route: "/api/libraries/" + ids["library"] + "/authors", capture: "authorList"},
		{id: "author.temp.image", who: "root", method: "POST", routeFn: authorRoute("Temp Author", "/image"), bodyFn: fixtureBody("author.png"), events: 1},
		{id: "author.temp.image.get", routeFn: authorRoute("Temp Author", "/image?width=64&format=jpeg"), binary: "bytes"},
		{id: "author.temp.delete.listener", who: "listener", method: "DELETE", routeFn: authorRoute("Temp Author", "")},
		{id: "author.temp.delete", who: "root", method: "DELETE", routeFn: authorRoute("Temp Author", ""), events: 1},
		{id: "author.temp.delete.again", who: "root", method: "DELETE", routeFn: authorRoute("Temp Author", "")},
		{id: "author.temp.image.after", routeFn: authorRoute("Temp Author", "/image?width=64&format=jpeg"), binary: "bytes"},
		{id: "author.temp.item", who: "root", route: "/api/items/" + ids["saga2"] + "?expanded=1"},
		{id: "author.image.delete.listener", who: "listener", method: "DELETE", routeFn: authorRoute("Terry Fixture", "/image")},
		{id: "author.image.delete", who: "root", method: "DELETE", routeFn: authorRoute("Terry Fixture", "/image"), events: 1},
		{id: "author.image.delete.again", who: "root", method: "DELETE", routeFn: authorRoute("Terry Fixture", "/image")},
		{id: "author.image.after.delete", routeFn: authorRoute("Terry Fixture", "/image?width=200&format=jpeg"), binary: "bytes"},
		{id: "author.image.after.delete.raw", routeFn: authorRoute("Terry Fixture", "/image?raw=1"), binary: "bytes"},
		{id: "author.final.list", who: "root", route: "/api/libraries/" + ids["library"] + "/authors"},
		{id: "series.get.long", who: "root", routeFn: seriesRoute("Long Saga", "")},
		{id: "series.get.long.progress", who: "root", routeFn: seriesRoute("Long Saga", "?include=progress")},
		{id: "series.get.mega.progress.rss", who: "root", routeFn: seriesRoute("Mega Cycle", "?include=progress,rssfeed")},
		{id: "series.get.mega.spaced", who: "root", routeFn: seriesRoute("Mega Cycle", "?include=%20progress%20,%20rssfeed%20,,")},
		{id: "series.get.long.rss", who: "root", routeFn: seriesRoute("Long Saga", "?include=rssfeed")},
		{id: "series.get.mega.listener", who: "listener", routeFn: seriesRoute("Mega Cycle", "?include=progress")},
		{id: "series.get.mega.finisher", who: "finisher", routeFn: seriesRoute("Mega Cycle", "?include=progress")},
		{id: "series.get.anon", routeFn: seriesRoute("Long Saga", "")},
		{id: "series.get.missing", who: "root", route: "/api/series/00000000-0000-4000-8000-000000000000"},
		{id: "series.get.badid", who: "root", route: "/api/series/not-a-uuid"},
		{id: "series.update.listener", who: "listener", method: "PATCH", routeFn: seriesRoute("Long Saga", ""), body: map[string]any{"name": "x"}},
		{id: "series.update.empty", who: "root", method: "PATCH", routeFn: seriesRoute("Long Saga", ""), body: map[string]any{}},
		{id: "series.update.invalid", who: "root", method: "PATCH", routeFn: seriesRoute("Long Saga", ""), body: map[string]any{"name": 5, "description": nil, "other": "x"}},
		{id: "series.update.missing", who: "root", method: "PATCH", route: "/api/series/00000000-0000-4000-8000-000000000000", body: map[string]any{"name": "x"}},
		{id: "series.update.rename", who: "root", method: "PATCH", routeFn: seriesRoute("Long Saga", ""), body: map[string]any{"name": "The Long Saga Renamed", "description": "A saga in two parts."}, events: 1},
		{id: "series.update.nochange", who: "root", method: "PATCH", routeFn: seriesRoute("Long Saga", ""), body: map[string]any{"name": "The Long Saga Renamed", "description": "A saga in two parts."}},
		{id: "series.update.description", who: "root", method: "PATCH", routeFn: seriesRoute("Long Saga", ""), body: map[string]any{"description": ""}, events: 1},
		{id: "series.after.get", who: "root", routeFn: seriesRoute("Long Saga", "?include=progress,rssfeed")},
		{id: "series.after.list", who: "root", route: "/api/libraries/" + ids["library"] + "/series?limit=20&page=0&sort=name&desc=0&minified=1"},
	}
}
